import{showAnswerFeedback,clearAnswerFeedback}from'./answer-feedback.js?v=7';
import{apiFetch}from'./chat-api.js';
import{restoreJourney,claim}from'./journey.js?v=7';
import{topics,blank,record,status,applyAnswer,recommend,question,parseAnswer,load,buildingCount}from'./learning.js?v=7';
const $=id=>document.getElementById(id);let journey;try{journey=restoreJourney(localStorage.getItem('math-voyage-v3')||localStorage.getItem('math-voyage-v2'),localStorage.getItem('math-galaxy-v1'));}catch{journey=restoreJourney(null,null);}let state=journey.learning;let filter='全部星系',selected=null,q=null,helped=false,answered=false,controller=null,chatHistory=[],apiReady=false;const symbols=['＋','½','±','√','x','✳','=','xy','>','x²','↗','÷','∪','∠','△','⊿','⋈','○','▥','⚄'];
function save(){try{for(let t of topics)claim(journey,t.id);localStorage.setItem('math-voyage-v3',JSON.stringify(journey));}catch{$('storageWarning').textContent='当前浏览器无法保存进度，请保持页面打开。';}}
const classFor=s=>({'掌握':'master','补强':'weak','练习':'practice','未探索':''}[s]);
function render(){let next=recommend(state);$('stage').value=state.stage;$('filters').replaceChildren();for(let g of ['全部星系',...new Set(topics.map(t=>t.group))]){let b=document.createElement('button');b.textContent=g;b.className=g===filter?'active':'';b.onclick=()=>{filter=g;render();};$('filters').append(b);}$('nodes').replaceChildren();$('edges').replaceChildren();for(let [i,t]of topics.entries()){if(filter!=='全部星系'&&t.group!==filter)continue;let s=status(state,t.id),b=document.createElement('button');b.className=`planet ${classFor(s)} ${t.id===next.id?'recommended':''}`;b.dataset.group=t.group;b.style.left=t.x+'%';b.style.top=(t.y*.87+5)+'%';b.setAttribute('aria-label',`${t.name}，${s}`);b.innerHTML=`<span class="orb">${s==='掌握'?'✓':symbols[i]}</span><span>${t.name}</span>${t.id===next.id?'<span class="tag">✦ 推荐探索</span>':''}`;b.onclick=()=>open(t.id);$('nodes').append(b);for(let p of t.pre){let a=topics.find(x=>x.id===p);if(filter!=='全部星系'&&a.group!==filter)continue;let line=document.createElementNS('http://www.w3.org/2000/svg','line');for(let[k,v]of Object.entries({x1:a.x,y1:a.y*.87+5,x2:t.x,y2:t.y*.87+5}))line.setAttribute(k,v);if(status(state,p)==='掌握')line.classList.add('lit');$('edges').append(line);}}let count=topics.filter(t=>status(state,t.id)==='掌握').length;$('mastered').textContent=count;$('attempts').textContent=state.total;$('bar').style.width=count/topics.length*100+'%';$('progressText').textContent=count?`已点亮 ${count} / ${topics.length} 颗基础知识星球。`:'不着急，第一颗星就在前方。';$('recommendName').textContent=next.name;let weak=topics.find(t=>status(state,t.id)==='补强');$('recommendReason').textContent=weak?(weak.id===next.id?'再用一题不同的练习，慢慢找回思路。':`刚才在「${weak.name}」遇到了困难，建议先检查这块基础。`):'从这里出发，用一道小题发现自己已经会了什么。';$('go').textContent=state.total?'继续我的探索 ↗':'开始我的探索 ↗';if(!$('report').hidden)report();}
function report(){let box=$('report');box.replaceChildren();let h=document.createElement('h2');h.textContent='我的航行记录';box.append(h);let p=document.createElement('p');p.textContent='掌握表示完成本版基础题验证，不等同于中考综合题全部掌握。补强状态只来自实际答题，前置主题不会被自动判错。';box.append(p);let ul=document.createElement('ul');for(let t of topics){let li=document.createElement('li'),b=document.createElement('button');b.textContent=`${t.name} · ${status(state,t.id)} (${Math.min(3,record(state,t.id).wins.length)}/3)`;b.onclick=()=>open(t.id);li.append(b);ul.append(li);}box.append(ul);}
function open(id){cancelChat();selected=topics.find(t=>t.id===id);chatHistory=[];$('messages').replaceChildren();message('你好呀！这里是「'+selected.name+'」星球。可以告诉我你卡在哪一步，我会陪你拆成小步骤。');$('topicGroup').textContent=selected.group;$('topicName').textContent=selected.name;$('lessonText').textContent=selected.lesson;newQuestion();if(!$('lesson').open)$('lesson').showModal();$('answer').focus();}
function newQuestion(){clearAnswerFeedback();cancelChat();let r=record(state,selected.id);q=question(selected.id,r.attempts);helped=!!r.helpedKeys?.includes(q.key);answered=false;$('question').textContent=q.q;$('questionNumber').textContent=`基础练习 · 第 ${r.attempts+1} 次探索`;$('milestones').textContent=Array.from({length:3},(_,i)=>i<r.wins.length?'★':'☆').join(' ');$('feedback').textContent='';$('answer').value='';$('answer').disabled=false;$('check').disabled=false;$('next').hidden=true;$('skip').hidden=false;$('hint').disabled=false;$('answer').focus();}
$('answerForm').onsubmit=e=>{e.preventDefault();if(answered)return;let n=parseAnswer($('answer').value);if(!Number.isFinite(n)){$('feedback').textContent='请输入一个数字、小数或分数（例如 1/2），再试一次。';return;}let correct=Math.abs(n-q.ans)<1e-8;const previousBuildings=buildingCount(state,selected.id),previousWins=record(state,selected.id).wins.length,rewardedBefore=journey.claimed.includes(selected.id);applyAnswer(state,selected.id,q,correct,helped);save();answered=true;$('answer').disabled=true;$('check').disabled=true;$('next').hidden=false;$('skip').hidden=true;$('feedback').className=correct?'good':'';$('feedback').textContent=(correct?(helped?'答对啦！这次是有帮助的练习，下题试着独立完成。':status(state,selected.id)==='掌握'?'星球点亮啦！你独立完成了 3 道不同题目。':'答对啦！又向点亮星球迈进了一步。'):'暂时没答对也没关系，我们一起看一看：')+' '+q.explain;$('milestones').textContent=Array.from({length:3},(_,i)=>i<record(state,selected.id).wins.length?'★':'☆').join(' ');render();showAnswerFeedback({correct,helped,awarded:!rewardedBefore&&journey.claimed.includes(selected.id),wins:record(state,selected.id).wins.length,previousWins,buildings:buildingCount(state,selected.id),previousBuildings});};
$('next').onclick=newQuestion;$('hint').onclick=()=>{markHelp();message(q.hint);$('feedback').textContent='提示已放在三三的聊天框中。这题会作为有帮助的练习。';};$('skip').onclick=()=>{if(answered)return;applyAnswer(state,selected.id,q,false,true);save();render();let t=recommend(state);message(`不用着急。我们可以先看看「${t.name}」。`);$('feedback').textContent='已标记为需要补强。点击下一道继续，或返回星图前往推荐星球。';answered=true;$('answer').disabled=true;$('check').disabled=true;$('next').hidden=false;$('skip').hidden=true;};
$('close').onclick=()=>$('lesson').close();$('lesson').addEventListener('close',cancelChat);$('stage').onchange=()=>{state.stage=$('stage').value;save();render();};$('go').onclick=$('routeGo').onclick=()=>open(recommend(state).id);$('listToggle').onclick=()=>{let on=$('galaxy').classList.toggle('list');$('listToggle').textContent=on?'切换星图 ✧':'切换列表 ☷';};$('reportTab').onclick=()=>{$('report').hidden=false;report();$('reportTab').classList.add('active');$('mapTab').classList.remove('active');$('report').scrollIntoView({behavior:'smooth'});};$('mapTab').onclick=()=>{$('report').hidden=true;$('mapTab').classList.add('active');$('reportTab').classList.remove('active');document.querySelector('.map-card').scrollIntoView({behavior:'smooth'});};
function markHelp(){helped=true;let r=record(state,selected.id);state.records[selected.id]={...r,helpedKeys:[...new Set([...(r.helpedKeys||[]),q.key])]};save();}
function message(text,user=false){let el=document.createElement('div');el.className='bubble'+(user?' user':'');el.textContent=text;$('messages').append(el);el.scrollIntoView({block:'nearest'});return el;}
function cancelChat(){if(controller){let requestId=controller.requestId;controller.abort();controller=null;if(requestId)apiFetch('/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestId}),keepalive:true}).catch(()=>{});}$('send').textContent='↑';$('send').setAttribute('aria-label','发送消息');}
async function ask(text){if(!text.trim()||!selected)return;if(controller){cancelChat();return;}markHelp();message(text,true);$('chatInput').value='';if(!apiReady){message('当前使用离线提示，暂不能自由问答。'+(/简单|理解|知识/.test(text)?selected.lesson:q.hint));return;}let localController=new AbortController();controller=localController;let topicId=selected.id;let requestId=crypto.randomUUID();localController.requestId=requestId;let bubble=message('三三正在想办法讲得更清楚…');$('send').textContent='■';$('send').setAttribute('aria-label','停止回答');let timer=setTimeout(()=>{if(controller===localController)cancelChat();},165000);try{let res=await apiFetch('/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestId,topicId,questionIndex:record(state,topicId).attempts-(answered?1:0),message:text,history:chatHistory.slice(-8)}),signal:localController.signal});let data=await res.json();if(!res.ok)throw Error(data.error||'服务暂时不可用');if(selected.id!==topicId)return;bubble.textContent=data.reply;chatHistory.push({role:'user',content:text},{role:'assistant',content:data.reply});}catch(e){bubble.textContent=localController.signal.aborted?'这次回答已停止或超时。可以重新发送问题。':(e.message||'三三暂时没连上问答服务，请稍后重试。');}finally{clearTimeout(timer);if(controller===localController){controller=null;$('send').textContent='↑';$('send').setAttribute('aria-label','发送消息');}}}
$('chatForm').onsubmit=e=>{e.preventDefault();if(controller){cancelChat();return;}ask($('chatInput').value);};document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>ask(b.dataset.prompt));apiFetch('/health').then(r=>r.ok?r.json():null).then(d=>{apiReady=d?.agentcore===true;$('chatMode').textContent=apiReady?'三三在线 · AWS AgentCore':'离线提示 · 自由问答未连接';}).catch(()=>{$('chatMode').textContent='离线提示 · 自由问答未连接';});render();
